  const conflicts=[];
  jobs.forEach(t=>predecessorIds(t).forEach(id=>{const p=byId.get(id);if(p&&t.start&&p.due&&t.start<=p.due)conflicts.push({jobId:t.id,predecessorId:id,job:t.title,predecessor:p.title});}));
